#include <cuda_fp16.h>
#include <cuda_runtime.h>

template<typename scalar_t>
__global__ void mean_reduce_kernel(const scalar_t* input, scalar_t* output, 
                                   int64_t total_elements, int64_t reduce_dim_size, 
                                   int64_t outer_size, int64_t inner_size) {
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= outer_size * inner_size) return;

    int64_t outer_idx = idx / inner_size;
    int64_t inner_idx = idx % inner_size;

    scalar_t sum = 0;
    for (int64_t i = 0; i < reduce_dim_size; ++i) {
        int64_t input_idx = outer_idx * reduce_dim_size * inner_size + i * inner_size + inner_idx;
        sum += input[input_idx];
    }

    int64_t output_idx = outer_idx * inner_size + inner_idx;
    output[output_idx] = sum / static_cast<scalar_t>(reduce_dim_size);
}

torch::Tensor mean_reduce_forward(const torch::Tensor& input, int64_t dim) {
    TORCH_CHECK(input.dtype() == torch::kFloat16, "Input must be float16");

    auto input_sizes = input.sizes();
    int64_t total_elements = input.numel();

    // Calculate dimensions
    int64_t reduce_dim_size = input_sizes[dim];
    int64_t outer_size = 1;
    int64_t inner_size = 1;

    for (int64_t i = 0; i < dim; ++i) {
        outer_size *= input_sizes[i];
    }

    for (int64_t i = dim + 1; i < input_sizes.size(); ++i) {
        inner_size *= input_sizes[i];
    }

    // Create output tensor
    std::vector<int64_t> output_sizes;
    for (int64_t i = 0; i < input_sizes.size(); ++i) {
        if (i != dim) {
            output_sizes.push_back(input_sizes[i]);
        }
    }

    auto options = torch::TensorOptions().dtype(torch::kFloat16).device(torch::kCUDA);
    torch::Tensor output = torch::empty(output_sizes, options);

    // Launch kernel
    const int block_size = 256;
    const int grid_size = (outer_size * inner_size + block_size - 1) / block_size;

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(input.scalar_type(), "mean_reduce_kernel", ([&] {
        mean_reduce_kernel<scalar_t><<<grid_size, block_size, 0, at::cuda::getCurrentCUDAStream()>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            total_elements,
            reduce_dim_size,
            outer_size,
            inner_size
        );
    }));

    return output;
}
"""

