    batch_size = 128
    dim1 = 4096
    dim2 = 4095
    x = torch.rand(batch_size, dim1, dim2, dtype=torch.float16, device='cuda')
    return [x]

def get_init_inputs():
    return [1]

class ModelNew(torch.nn.Module):
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Compile and load the CUDA extension
        compiled_module = load_inline(
            name="mean_reduce_ext",
            cpp_sources=cuda_source,
            cuda_sources=cuda_source,
            functions=["mean_reduce_forward"],
            verbose=False
        )

        # Call the CUDA kernel
        return compiled_module.mean_reduce_forward(x, self.dim)

# Test the implementation
